const SQL = `INSERT INTO "LookupOption"
  ("id","type","value","sortOrder","isActive","code","defaultState","createdAt","updatedAt")
VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
ON CONFLICT ("type","value") DO UPDATE SET
  "sortOrder" = EXCLUDED."sortOrder", "isActive" = EXCLUDED."isActive",
  "code" = EXCLUDED."code", "defaultState" = EXCLUDED."defaultState", "updatedAt" = EXCLUDED."updatedAt"`;

async function main() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("Set DATABASE_URL to the target database.");
  const pool = new Pool({ connectionString: url });
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    for (const r of ROWS) await client.query(SQL, r);
    await client.query("COMMIT");
    const { rows } = await client.query('SELECT type, count(*)::int AS n FROM "LookupOption" GROUP BY type ORDER BY type');
    console.log(`Seeded ${ROWS.length} LookupOption rows. Target now has:`);
    console.table(rows);
  } catch (e) {
    await client.query("ROLLBACK");
    throw e;
  } finally {
    client.release();
    await pool.end();
  }
}

main().catch((e) => { console.error(e); process.exit(1); });
